# [LATER-STEP] live_caption_translate.py\n# Translate live speech captions from one language to another using IBM Watson\n# Language Translator (hosted) and the streaming captions generated by the same-\n# scenario files.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import LanguageTranslatorV3\nfrom ibm_cloud_sdk_core.authenticators import IAMAuthenticator\n\n# ----------------------------------------------------------\n# Configuration read from environment variables\n# ----------------------------------------------------------\nLANG_SRC = os.getenv('STT_SRC_LANG', 'en')          # source language code\nLANG_TGT = os.getenv('STT_TGT_LANG', 'es')          # target language code\nAPIKEY = os.getenv('LANGT_TRANSLATOR_APIKEY')\nURL = os.getenv('LANGT_TRANSLATOR_URL')  # e.g., 'https://api.us-south.language-translator.watson.cloud.ibm.com'\nif not APIKEY or not URL:\n    print('Set LANGT_TRANSLATOR_APIKEY and LANGT_TRANSLATOR_URL')\n    sys.exit(1)\nauthenticator = IAMAuthenticator(APIKEY)\ntranslator = LanguageTranslatorV3(\n    version='2022-01-26',\n    authenticator=authenticator,\n)\ntranslator.set_service_url(URL)\n\n# ----------------------------------------------------------\n# Helper: translate a single text segment\n# ----------------------------------------------------------\nasync def translate_text(text: str) -> str:\n    \"\"\"Translate `text` from LANG_SRC to LANG_TGT.\n\n    Returns the translated string.\n    \"\"\"\n    try:\n        response = translator.translate(\n            text=text,\n            source=LANG_SRC,\n            target=LANG_TGT,\n        ).get_result()\n        translated = response.get('translations', [{}])[0].get('translation', '')\n        return translated\n    except Exception as e:\n        print('Translation error:', e)\n        return ''\n\n# ----------------------------------------------------------\n# Integration with streaming caption source\n# ----------------------------------------------------------\n# This example assumes the presence of a generator `caption_generator()` that\n# yields interim/final transcript chunks (e.g., from partial_results.py).\n#\n# For demonstration, a dummy generator is provided.\n# ----------------------------------------------------------\nasync def caption_generator():\n    # Simulate live caption chunks (replace with real callback)\n    yield {'transcript': 'Hello world', 'final': False}\n    yield {'transcript': 'How are you', 'final': True}\n    yield {'transcript': 'Goodbye', 'final': True}\n\n# ----------------------------------------------------------\n# Main loop: stream captions, translate, and print\n# ----------------------------------------------------------\nasync def main():\n    async for chunk in caption_generator():\n        txt = chunk['transcript']\n        print('-> Received:', txt)\n        if txt:\n            translated = await translate_text(txt)\n            print('Translated:', translated)\n\n# ----------------------------------------------------------\n# Run\n# ----------------------------------------------------------\nif __name__ == '__main__':\n    asyncio.run(main())\n